gr7(){return"\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0623-\u064a"},
gA5(){return"\u064a\u062f\u0648\u064a"},
gom(){return"\u0645\u062c\u0644\u062f \u062c\u062f\u064a\u062f"},
