gr3(){return"\u0418\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0435"},
gqs(){return"\u041f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u0431\u043e\u043b\u044c\u0448\u0435"},
gA6(){return"\u041c\u043e\u0438 \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u044b\u0435"},
gA7(){return"\u041f\u043e\u0438\u0441\u043a \u0442\u0440\u0435\u043a\u0430 \u0438\u043b\u0438 \u0438\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044f"},
gzT(){return"\u0418\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0433\u043e \u043f\u043e\u043a\u0430 \u043d\u0435\u0442. \u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043d\u0430 \u0441\u0435\u0440\u0434\u0446\u0435 \u0443 \u0442\u0440\u0435\u043a\u0430, \u0447\u0442\u043e\u0431\u044b \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0435\u0433\u043e."},
gr6(){return"\u041d\u0435\u0434\u0430\u0432\u043d\u0438\u0435"},
gr5(){return"\u0421\u0442\u0430\u0440\u044b\u0435"},
gr4(){return"\u0418\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c \u0410-\u042f"},
gr7(){return"\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u0410-\u042f"},
gA5(){return"\u0412\u0440\u0443\u0447\u043d\u0443\u044e"},
gom(){return"\u041d\u043e\u0432\u0430\u044f \u043f\u0430\u043f\u043a\u0430"},
gA3(){return"\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u043f\u0430\u043f\u043a\u0438"},
gzY(){return"\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u044d\u043c\u043e\u0434\u0437\u0438"},
gzX(){return"\u0422\u043e\u043b\u044c\u043a\u043e \u043e\u0434\u0438\u043d \u044d\u043c\u043e\u0434\u0437\u0438, \u0431\u0435\u0437 \u0442\u0435\u043a\u0441\u0442\u0430."},
gA_(){return"\u041e\u043f\u0438\u0441\u0430\u043d\u0438\u0435 (\u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e)"},
gA4(){return"\u041d\u0435\u0434\u0430\u0432\u043d\u043e \u043f\u0440\u043e\u0441\u043b\u0443\u0448\u0430\u043d\u043e"},
gzW(){return"\u0421\u043e\u0437\u0434\u0430\u0442\u044c"},
gA0(){return"\u0418\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u043f\u0430\u043f\u043a\u0443"},
gr1(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c"},
gzZ(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u044d\u0442\u0443 \u043f\u0430\u043f\u043a\u0443? \u0422\u0440\u0435\u043a\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435 \u0431\u0443\u0434\u0443\u0442 \u0432 \u043d\u0435\u0439 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u044b."},
