gA1(){return"\u042d\u043c\u043e\u0434\u0437\u0438"},
gzV(){return"\u0426\u0432\u0435\u0442"},
gr2(){return"\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c"},
gA2(){return"\u042d\u0442\u0430 \u043f\u0430\u043f\u043a\u0430 \u043f\u0443\u0441\u0442\u0430. \u0423\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0439\u0442\u0435 \u0441\u0435\u0440\u0434\u0446\u0435 \u0443 \u0442\u0440\u0435\u043a\u0430, \u0447\u0442\u043e\u0431\u044b \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0435\u0433\u043e \u0441\u044e\u0434\u0430."},
